WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_conc_m_diff'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '不同溶液混合', 'kp-conc-m-diff', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "不同溶液混合基础"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "混合后的浓度必定在两杯原溶液的浓度之间，且偏向质量大的一方。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“一杯 10% 的盐水 100克，与一杯 20% 的盐水 300克混合……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、基础公式推导（如果不用十字交叉）"}]}, {"type": "katexBlock", "attrs": {"content": "C_{混} = \\frac{\\text{盐}_1 + \\text{盐}_2}{\\text{盐水}_1 + \\text{盐水}_2} = \\frac{100 \\times 10\\% + 300 \\times 20\\%}{100 + 300}"}}]}$$ AS jsonb), NULL, '不同溶液混合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "不同溶液混合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_m_diff", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
